import { Star, StarHalf } from 'lucide-react'

type StarRatingProps = {
  rating: number | null
  className?: string
}

const STAR_COUNT = 5

type StarState = 'full' | 'half' | 'empty'

function starStates(rating: number): StarState[] {
  const clamped = Math.min(STAR_COUNT, Math.max(0, rating))
  const halves = Math.round(clamped * 2)
  return Array.from({ length: STAR_COUNT }, (_, index) => {
    const remaining = halves - index * 2
    if (remaining >= 2) return 'full'
    if (remaining === 1) return 'half'
    return 'empty'
  })
}

function StarGlyph({ state }: { state: StarState }) {
  if (state === 'full') {
    return <Star aria-hidden="true" className="size-4 fill-star text-star" />
  }
  if (state === 'half') {
    return (
      <span className="relative inline-flex size-4">
        <Star aria-hidden="true" className="size-4 fill-transparent text-slate-300" />
        <StarHalf
          aria-hidden="true"
          className="absolute inset-0 size-4 fill-star text-star"
        />
      </span>
    )
  }
  return <Star aria-hidden="true" className="size-4 fill-transparent text-slate-300" />
}

export function StarRating({ rating, className }: StarRatingProps) {
  if (rating === null || !Number.isFinite(rating)) return null

  const classes = ['inline-flex items-center gap-0.5', className]
    .filter((part) => part !== undefined && part !== '')
    .join(' ')

  return (
    <span className={classes} role="img" aria-label={`Rated ${rating.toFixed(1)} out of 5`}>
      {starStates(rating).map((state, index) => (
        <StarGlyph key={index} state={state} />
      ))}
    </span>
  )
}

import { Mountain } from 'lucide-react'

type PlaceholderProps = {
  className?: string
}

export function Placeholder({ className }: PlaceholderProps) {
  const classes = [
    'flex items-center justify-center bg-chip text-muted',
    className,
  ]
    .filter((part) => part !== undefined && part !== '')
    .join(' ')

  return (
    <div role="img" aria-label="No photo available" className={classes}>
      <Mountain aria-hidden="true" className="size-10" strokeWidth={1.5} />
    </div>
  )
}

import { useState } from 'react'
import { Placeholder } from './Placeholder.tsx'

type ParkImageProps = {
  src: string | null
  alt: string
  className?: string
}

export function ParkImage({ src, alt, className }: ParkImageProps) {
  const [failedSrc, setFailedSrc] = useState<string | null>(null)
  const trimmed = src?.trim() ?? ''
  const missing = trimmed === ''
  const failed = !missing && failedSrc === trimmed

  if (missing || failed) {
    return <Placeholder className={className} />
  }

  const classes = ['block h-full w-full object-cover', className]
    .filter((part) => part !== undefined && part !== '')
    .join(' ')

  return (
    <img
      src={trimmed}
      alt={alt}
      className={classes}
      onError={() => setFailedSrc(trimmed)}
    />
  )
}

import type { ReactNode } from 'react'
import { ChevronLeft } from 'lucide-react'
import { Link } from 'react-router-dom'

type BackLinkProps = {
  to?: string
  children?: ReactNode
  className?: string
}

export function BackLink({
  to = '/',
  children = 'Back to all parks',
  className,
}: BackLinkProps) {
  const classes = [
    'inline-flex items-center gap-1 rounded-full bg-surface px-3 py-1.5 text-sm font-medium text-ink shadow-md',
    'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2',
    className,
  ]
    .filter((part) => part !== undefined && part !== '')
    .join(' ')

  return (
    <Link to={to} className={classes}>
      <ChevronLeft aria-hidden="true" className="size-4 shrink-0" />
      {children}
    </Link>
  )
}

type InfoRowProps = {
  label: string
  value: string | null
  className?: string
}

export function InfoRow({ label, value, className }: InfoRowProps) {
  if (value === null || value.trim() === '') return null

  const classes = ['flex items-baseline justify-between gap-4 py-2 text-sm', className]
    .filter((part) => part !== undefined && part !== '')
    .join(' ')

  return (
    <div className={classes}>
      <dt className="text-muted">{label}</dt>
      <dd className="text-right font-medium text-ink">{value}</dd>
    </div>
  )
}

import { getAmenity } from '../../lib/amenities.ts'

type AmenityChipProps = {
  slug: string
  className?: string
}

export function AmenityChip({ slug, className }: AmenityChipProps) {
  const { label, icon: Icon } = getAmenity(slug)
  const classes = [
    'inline-flex items-center gap-1.5 rounded-full bg-chip px-3 py-1 text-sm text-ink',
    className,
  ]
    .filter((part) => part !== undefined && part !== '')
    .join(' ')

  return (
    <span className={classes}>
      <Icon aria-hidden="true" className="size-4 shrink-0 text-primary" />
      {label}
    </span>
  )
}

